			/**
			 * 상세 페이지 CRUD 권한 처리 
			 * @param {"CREATE" | "READ" | "UPDATE"} psType CRUD Type
			 */
			function fn_setDtlCrud(psType) {
			    
			    console.log(psType);
			    
			    fn_callCommCd(); // 공통코드 조회  (subOnload 호출)
			    
			    if (psType == "READ") {
			        
			        msCrudType = "READ";
			        
			        app.lookup("dsDetail").clear(); // 상세정보
			        
			        util.Control.setReadOnly(app, true, ["grpData"]);
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]); // 저장, 삭제, 취소
			        if(mdfUseYn == 'Y') util.Control.setVisible(app, true, ["btnUpdate"]); // 수정
			        if(delUseYn == 'Y') util.Control.setVisible(app, true, ["btnDelete"]); // 삭제
			    } else {
			        
			        if (psType == "CREATE") {
			            
			            msCrudType = "CREATE";
			            
			            var dsServiceSubList = app.lookup("dsServiceSubList");
			            var nRow = dsServiceSubList.insertRow(0);
			            
			            // 데이터셋 클리어
			            app.lookup("dsDetail").clear(); // 상세정보
			            app.lookup("dsServiceSubList").clear(); // 서비스실행사업목록
			            app.lookup("dsDetail").addRow();
			            util.Control.setValue(app, "dti3", vsYear);
			            app.lookup("dsDetail").setValue(0, "USE_YN", "Y");
			            dsServiceSubList.setValue(0, "REQSTD_INDCT_YN", "N");
			            
			            if(regUseYn == 'Y') util.Control.setVisible(app, true, ["btnSave"]); // 저장, 목록, 닫기
			            util.Control.setVisible(app, false, ["btnUpdate", "btnDelete", "btnRestore"]); // 수정, 삭제, 취소
			        } else if (psType == "UPDATE") {
			            
			            msCrudType = "UPDATE";
			            
			            util.Control.setReadOnly(app, false, ["grpData"]);
			            
			            if(mdfUseYn == 'Y') util.Control.setVisible(app, true, ["btnSave", "btnRestore"]); // 저장, 취소
			            util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]); // 수정, 삭제, 목록, 닫기
			        }
			    }
			    
			    util.Control.redraw(app, "grpData");
			}

