			/** 시작일보다 빠른일자인경우 날자범위 확인
			 * @param {String} startVal
			 * @param {String} endVal
			 */
			function isDateBetweenChk(startVal, endVal) {
			    
			    /* YOO.CHI.HOON 2023-01-26 신청일자 날짜범위체크*/
			    var startDateVal = ValueUtil.fixNumber(startVal);
			    var endDateVal   = ValueUtil.fixNumber(endVal);

			    var isBetweenVal = startDateVal - endDateVal;
			    
			    /* retrn + 시작범위보다 아래*/
			    return isBetweenVal;
			}

