			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick( /* cpr.events.CMouseEvent */ e) {
			    
			    var btnSave = e.control;
			    
			    // 프리폼 필수값 유효성 체크 (저장 confirm 전에 체크)
			    if (!util.validate(app, "grp2")) return false; // 서비스사업정보
			    if (!util.validate(app, "grdList")) return false;    
			    
			    var rowIdx = app.lookup("grdList").getSelectedRowIndex();
			    
			    //사업연도
			    var srvcYn = app.lookup("dti3").value;
			    var endYn = app.lookup("dsDetail").getValue(0, "BIZ_END_YMD").substring(0, 4);
			    var strYn = app.lookup("dsDetail").getValue(0, "BIZ_BGNG_YMD").substring(0, 4);
			    
			    var voDataSet = app.lookup("dsServiceSubList");
			    var rowCnt    = voDataSet.getRowCount();
			    var duplCnt   = 0;
			    
			    /* 2023.08.07 실행사업분류 필수로 변경 */
			    for(var i = 0; i < rowCnt; i++){
			        var excnBizSe = voDataSet.getValue(i, "EXCN_BIZ_CL_SE_CD");
			        if(voDataSet.getRowState(i) != cpr.data.tabledata.RowState.DELETED ){
			            if(ValueUtil.isNull(excnBizSe)){
			                var eRow = i+1;
			                var eMsg = eRow + "행의 실행사업분류를 선택해주세요.";
			                util.Msg.alert(app, eMsg);
			                return false;
			            }
			        }
			    }
			    
			    /* 신청일자 신청종료일자 validation 추가*/
			    if (untTaskwk == "U07" || untTaskwk == "U08") {
			        if(rowCnt > 0){
			            for(var idx = 0; idx < rowCnt; idx++){
			                
			                var startVal = voDataSet.getRowData(idx).APLY_BGNG_YMD;
			                var endVal   = voDataSet.getRowData(idx).APLY_END_YMD;
			                
			                if(isDateBetweenChk(startVal,endVal) >= 1){
			                    duplCnt ++;
			                    break;           
			                }
			            }
			            if (duplCnt > 0){
			                var psTitle = '신청일자';
			                var psMsgId = '서비스실행사업 목록의 ' + (idx+1) +  '번째 데이터에서\n신청일자보다 종료일자가 작습니다.';
			                
			                util.Msg.alert(app, psMsgId, null, function(){
			                }, psTitle);
			                return false;          
			            }
			        }
			    }    
			    
			    var voDataSet1 = app.lookup("dsServiceSubList");
			    var voSrvcExcnBizNm = voDataSet1.getColumnData("SRVC_EXCN_BIZ_NM");
			    
			    for (var i = 0; i < voSrvcExcnBizNm.length; i++) {
			        var dupChkCnt = 0;
			        for (var j = 0; j < voSrvcExcnBizNm.length; j++) {
			            
			            if (voSrvcExcnBizNm[i] == voSrvcExcnBizNm[j]) dupChkCnt++;
			        }
			        if (dupChkCnt > 1) {
			            break;
			        }
			    }
			    if (dupChkCnt > 1) {
			        var psMsgId = "동일한 서비스실행사업이 이미 등록되어있습니다.\n확인 후 다시 선택바랍니다.";
			        var psTitle = "서비스실행사업 중복오류";
			        util.Msg.alert(app, psMsgId, null, function() {
			            util.Control.setFocus(app, "ipb_SRVC_EXCN_BIZ_NM");
			        }, psTitle);
			        return false;
			    }
			    
			    // 미지원, 삭제 확인 추가
			    var bFlag = true;
			    var sMsg = "";
			    
			    var comList = AppUtil.getComponentList(app, "grpData", "combobox");
			    for (var i = 0; i < comList.length; i++) {
			        var comObj = comList[i];
			        var sText = comObj.text;
			        
			        if (sText.indexOf('삭제') > -1 || sText.indexOf('미지원') > -1) {
			            bFlag = false;
			            
			            var sFiledLabel = comObj.fieldLabel;
			            
			            if (ValueUtil.isNull(sMsg)) {
			                sMsg = sFiledLabel + "을(를) 확인해 주세요.";
			                
			            } else {
			                sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			            }
			        }
			        
			    }
			    if (!bFlag) {
			        util.Msg.alert(app, sMsg);
			        return false;
			    }
			    
			    util.Msg.confirm(app, "CRM-M001", null, function() {
			        
			        // 저장 하시겠습니까?
			        doSave("SAVE"); // 상세저장
			    }, function() {
			        
			    }, "저장확인");
			}

