			function fn_cmb6SelectBoxReDraw() {
			    var dsSgg = app.lookup("dsOrgRegionSgg"); //원본
			    var dsOrgRegion = app.lookup("dsOrgRegion"); // 사용할 dsSet
			    var dsDetail = app.lookup("dsDetail");
			    var ctpvSeCd = app.lookup("dsDetail").getValue(0, "CTPV_SE_CD");
			    var sggCd = app.lookup("dsDetail").getValue(0, "SGG_CD");
			    dsOrgRegion.clear();
			    var ctpvCd = sggCd.substring(0,2);
			    var arrTmp = new Array();
			    if (ValueUtil.isNull(ctpvSeCd)) { // 기존 데이터 예외 처리용. 로직
			        for (var i=0; i < dsSgg.getRowCount(); i++) {
			            if (dsSgg.getValue(i, "SGG_CD") == sggCd)  {
			                var newRowData = {
			                    "SGG_CD" : dsSgg.getValue(i, "SGG_CD"),
			                    "SGG_NM" : dsSgg.getValue(i, "SGG_NM"),
			                    "CTPV_NM" : dsSgg.getValue(i, "CTPV_NM")
			                }
			                
			                dsOrgRegion.pushRowData(newRowData);
			                dsOrgRegion.commit();
			                
			                dsDetail.setValue(0, "SGG_CD", sggCd);
			                var ctpvCd = sggCd.substring(0,2);
			                dsDetail.setValue(0, "CTPV_SE_CD", ctpvCd);
			            }
			        }                
			    } else {
			        for (var i=0; i < dsSgg.getRowCount(); i++) {
			            if (dsSgg.getValue(i, "CTPV_SE_CD") == ctpvSeCd)  {
			                var newRowData = {
			                    "SGG_CD" : dsSgg.getValue(i, "SGG_CD"),
			                    "SGG_NM" : dsSgg.getValue(i, "SGG_NM"),
			                    "CTPV_NM" : dsSgg.getValue(i, "CTPV_NM")
			                }
			                
			                dsOrgRegion.pushRowData(newRowData);
			                dsOrgRegion.commit();
			            }
			        }
			        
			    }
			    
			    app.lookup("grp2").redraw();   
			}

